CREATE OR REPLACE FUNCTION public.assign_web_reservation_spot()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_spot uuid;
begin
 if new.source <> 'web' then return new; end if;
 if new.status not in ('pending_payment','confirmed','checked_in') then return new; end if;
 if new.assigned_spot_id is not null then return new; end if;
 perform pg_advisory_xact_lock(hashtext('parking_inventory')::bigint);
 select p.id into v_spot from public.parking_spots p
 where p.active and p.inventory_state='available' and (p.polyvalent or p.vehicle_type_id=new.vehicle_type_id)
 and not exists(select 1 from public.capacity_blocks b where b.active and b.spot_id=p.id and b.starts_at<new.exit_at and b.ends_at>new.entry_at)
 and not exists(select 1 from public.reservations r where r.assigned_spot_id=p.id and r.id is distinct from new.id and r.status in ('confirmed','checked_in','pending_payment') and (r.status<>'pending_payment' or coalesce(r.expires_at,now()+interval '1 second')>now()) and r.entry_at<new.exit_at and (r.exit_at>new.entry_at or (r.finished_at is null and not r.rotation_pending and exists(select 1 from public.parking_sessions held where held.reservation_id=r.id))))
 and not exists(select 1 from public.parking_sessions ps where ps.spot_id=p.id and ps.status='inside' and true)
 order by random() limit 1;
 if v_spot is null then raise exception 'No hay una plaza libre para asignar durante las fechas solicitadas'; end if;
 new.assigned_spot_id:=v_spot;
 return new;
end;$function$

CREATE OR REPLACE FUNCTION public.parking_rotation_to_stay(p_session_id uuid, p_hotel_id uuid, p_vehicle_type_id uuid, p_spot_id uuid, p_days integer, p_model text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare ctx jsonb;s public.rotation_sessions;v_res jsonb;
begin
 ctx:=public.rotation_operator_context();select * into s from public.rotation_sessions where id=p_session_id for update;
 if not found then raise exception 'Ticket inexistente';end if;
 if s.converted_reservation_id is not null then return jsonb_build_object('id',s.converted_reservation_id,'already_converted',true);end if;
 if s.status<>'inside' or s.billing_only then raise exception 'Este ticket no se puede convertir a estancia';end if;
 if nullif(btrim(p_model),'') is null then raise exception 'Indica marca y modelo';end if;
 if s.entry_at+make_interval(days=>p_days)<=clock_timestamp() then raise exception 'La estancia debe cubrir hasta después de la hora actual';end if;
 perform 1 from public.parking_spots where id=p_spot_id and vehicle_type_id=p_vehicle_type_id and active for update;if not found then raise exception 'Selecciona una plaza válida';end if;
 v_res:=public.create_hotel_paid_reservation(p_hotel_id,p_vehicle_type_id,s.entry_at,p_days,s.plate,p_model,s.client_text,null,null,'Convertida desde ticket de rotación '||s.ticket_number);
 perform public.backoffice_check_in((v_res->>'id')::uuid,p_spot_id,s.entry_at);
 update public.rotation_sessions set status='cancelled',converted_reservation_id=(v_res->>'id')::uuid,updated_at=clock_timestamp() where id=s.id;
 return v_res;
end $function$
